    cityNo = 10
    graph = randTSP(cityNo)
    
    iterationNo = 1000
    
    p = Population(cityNo, graph, 100, 0.05, 0.4, iterationNo, keepBest=0)
    p.initialise()
    try:
        bestEver = []
        bestScore = inf
        for i in range(iterationNo):
            p.iterate()
            best, f = p.best()
            # copies of the most common tour, a rough sign of how converged the population is
            rn = repeatCount([s.perm for s in p.pop])
            print("Generation: " + repr(i))
            # print(repr(best) + " : " + repr(f))
            print("fitness value : " + repr(f))
            print("max repeats   : " +  repr(rn) + "\n")
            
            if f < bestScore:
                bestEver = best
                bestScore = f

        p.iterate()
        best, f = p.best()
    # ctrl+c stops early and still prints the best found so far
    except KeyboardInterrupt:
        if f < bestScore:
            bestEver = best
            bestScore = f
        
    print("Final Result: ")
    print(repr(best) + " : " + repr(f))

    if p.keepBest == 0:    
        print("\nBest Ever Achieved")
        print(repr(bestEver) + " : " + repr(bestScore))
    